<?php
require_once __DIR__.'/includes/functions.php';require_role(['donor','admin']);$errors=[];$categories=['Vegetarian','Non-Vegetarian','Vegan','Bakery','Fruits','Other'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$food=trim($_POST['food_name']??'');$category=$_POST['category']??'';$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_FLOAT);$unit=trim($_POST['unit']??'');$description=trim($_POST['description']??'');$ingredients=trim($_POST['ingredients']??'');$allergens=trim($_POST['allergens']??'');$prepared=str_replace('T',' ',$_POST['prepared_at']??'');$expiry=str_replace('T',' ',$_POST['expiry_at']??'');$address=trim($_POST['pickup_address']??'');$locality=trim($_POST['locality']??'');$contact=trim($_POST['contact_number']??'');$instructions=trim($_POST['pickup_instructions']??'');
if($food===''||mb_strlen($food)>150)$errors[]='Enter a food name up to 150 characters.';if(!in_array($category,$categories,true))$errors[]='Choose a valid food category.';if($qty===false||$qty<=0||$qty>99999)$errors[]='Enter a valid quantity greater than zero.';if($unit===''||mb_strlen($unit)>30)$errors[]='Enter a quantity unit.';if($description==='')$errors[]='Add a short food description.';if(!$prepared||strtotime($prepared)===false||strtotime($prepared)>time())$errors[]='Preparation time must be a valid time in the past.';if(!$expiry||strtotime($expiry)<=time())$errors[]='Expiry time must be in the future.';if($address===''||$locality===''||$contact==='')$errors[]='Pickup address, locality, and contact number are required.';
$image=null;if(!$errors){try{$image=safe_upload($_FILES['image']??[]);}catch(Throwable $e){$errors[]=$e->getMessage();}}
if(!$errors){$stmt=$pdo->prepare("INSERT INTO food_donations (donor_id,food_name,category,description,ingredients,allergens,quantity,unit,remaining_quantity,prepared_at,expiry_at,pickup_address,locality,contact_number,image,pickup_instructions,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?, 'Active')");$stmt->execute([current_user()['id'],$food,$category,$description,$ingredients,$allergens,$qty,$unit,$qty,date('Y-m-d H:i:s',strtotime($prepared)),date('Y-m-d H:i:s',strtotime($expiry)),$address,$locality,$contact,$image,$instructions]);flash('success','Your food listing is live. Thank you for sharing!');redirect('food-details.php?id='.$pdo->lastInsertId());}}
$page_title='Donate surplus food | SharePlate';require __DIR__.'/includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Make a difference nearby</p><h1>Share your surplus food</h1><p>Tell your community what is available and when it should be collected.</p></div></section><section class="container form-section"><div class="form-card wide"><h2>Food listing details</h2><p class="muted">Fields marked required help recipients make a safe pickup plan.</p><?php foreach($errors as $error):?><div class="alert alert-error"><?=e($error)?></div><?php endforeach;?>
<form method="post" enctype="multipart/form-data" class="stack-form two-col" data-validate><?=csrf_field()?><label>Food name *<input name="food_name" maxlength="150" required value="<?=e($_POST['food_name']??'')?>"></label><label>Category *<select name="category" required><option value="">Select category</option><?php foreach($categories as $c):?><option <?=($_POST['category']??'')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label>Quantity *<input type="number" name="quantity" min="0.01" step="0.01" required value="<?=e($_POST['quantity']??'')?>"></label><label>Unit *<input name="unit" maxlength="30" placeholder="servings, trays, kg" required value="<?=e($_POST['unit']??'')?>"></label><label class="span-two">Description *<textarea name="description" rows="3" required><?=e($_POST['description']??'')?></textarea></label><label>Ingredients<textarea name="ingredients" rows="2"><?=e($_POST['ingredients']??'')?></textarea></label><label>Allergen information<textarea name="allergens" rows="2" placeholder="List known allergens or enter None"><?=e($_POST['allergens']??'')?></textarea></label><label>Prepared at *<input type="datetime-local" name="prepared_at" required value="<?=e($_POST['prepared_at']??date('Y-m-d\TH:i'))?>"></label><label>Pickup deadline *<input type="datetime-local" name="expiry_at" required value="<?=e($_POST['expiry_at']??'')?>"></label><label class="span-two">Pickup address *<input name="pickup_address" maxlength="255" required value="<?=e($_POST['pickup_address']??current_user()['address']??'')?>"></label><label>City or locality *<input name="locality" maxlength="120" required value="<?=e($_POST['locality']??current_user()['locality']??'')?>"></label><label>Contact number *<input name="contact_number" type="tel" maxlength="30" required value="<?=e($_POST['contact_number']??current_user()['phone']??'')?>"></label><label>Food image <span class="optional">(JPG, PNG or WebP; max 4 MB)</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Pickup instructions<textarea name="pickup_instructions" rows="2"><?=e($_POST['pickup_instructions']??'')?></textarea></label><div class="span-two"><button class="button">Publish food listing</button></div></form></div></section><?php require __DIR__.'/includes/footer.php';?>